templates.prisma:
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Users {
  id String @id @default(uuid()) // Unique identifier for the user
  email String @unique // User's email address, used for login
  password_hash String // Hashed password for security
  role String @default("'owner'") // User role: 'owner', 'walker', 'admin'
  status String @default("'active'") // Account status: 'pending_verification', 'active', 'suspended', 'deleted'
  created_at DateTime // Timestamp of user creation
  updated_at DateTime // Timestamp of last update
}

model Owner_profiles {
  id String @id @default(uuid()) // Unique identifier for the owner profile
  user_id String @unique // Foreign key to the users table
  first_name String // Owner's first name
  last_name String // Owner's last name
  phone_number String? // Owner's contact phone number
  address String? // Owner's primary address
  emergency_contact_name String? // Name of emergency contact
  emergency_contact_phone String? // Phone of emergency contact

  // Relations:
  // [one-to-one] -> users (via user_id) [references]
}

model Walker_profiles {
  id String @id @default(uuid()) // Unique identifier for the walker profile
  user_id String @unique // Foreign key to the users table
  first_name String // Walker's first name
  last_name String // Walker's last name
  phone_number String? // Walker's contact phone number
  bio String? // Short biography of the walker
  experience_years Int? // Years of dog walking experience
  services_offered Json // JSON array of services offered (e.g., ['30-min walk', '60-min walk'])
  rates Json // JSON object of rates per service (e.g., {'30-min walk': 25.00})
  rating Float // Average rating from owners
  total_reviews Int // Total number of reviews received
  is_verified Boolean // Status after background check and admin approval
  service_radius_km Float @default(5) // Maximum distance from their location they will serve
  location Int? // Geographical point (latitude, longitude) for walker's base location

  // Relations:
  // [one-to-one] -> users (via user_id) [references]
}

model Pets {
  id String @id @default(uuid()) // Unique identifier for the pet
  owner_profile_id String // Foreign key to the owner_profiles table
  name String // Pet's name
  breed String? // Pet's breed
  age Int? // Pet's age in years
  weight_kg Float? // Pet's weight in kilograms
  temperament String? // Description of pet's temperament (e.g., 'friendly', 'shy', 'energetic')
  notes String? // Special instructions or medical notes for the pet
  profile_picture_url String? // URL to the pet's profile picture stored in S3

  // Relations:
  // [many-to-one] -> owner_profiles (via owner_profile_id) [references]
}

model Bookings {
  id String @id @default(uuid()) // Unique identifier for the booking
  owner_profile_id String // Foreign key to the owner_profiles table
  walker_profile_id String // Foreign key to the walker_profiles table
  pet_id String // Foreign key to the pets table (for the primary pet in the booking)
  service_type String // Type of service booked (e.g., '30-min walk', '60-min walk')
  booking_date DateTime // Date of the service
  start_time DateTime // Scheduled start time of the service
  end_time DateTime // Scheduled end time of the service
  duration_minutes Int // Expected duration of the walk in minutes
  status String @default("'pending_walker_acceptance'") // Current status of the booking: 'pending_walker_acceptance', 'accepted', 'started', 'completed', 'cancelled', 'disputed'
  total_price Float // Total cost of the service
  commission_amount Float // Amount taken by the platform as commission
  walker_payout_amount Float // Amount to be paid out to the walker
  actual_start_time DateTime? // Actual time the walk started
  actual_end_time DateTime? // Actual time the walk ended

  // Relations:
  // [many-to-one] -> owner_profiles (via owner_profile_id) [references]
  // [many-to-one] -> walker_profiles (via walker_profile_id) [references]
  // [many-to-one] -> pets (via pet_id) [references]
}

model Walk_tracks {
  id String @id @default(uuid()) // Unique identifier for the walk track entry
  booking_id String // Foreign key to the bookings table
  timestamp DateTime // Timestamp of the location update or event
  latitude Float // Latitude of the walker's current position
  longitude Float // Longitude of the walker's current position
  event_type String? @default("'location_update'") // Type of event: 'location_update', 'photo_taken', 'incident_reported'
  notes String? // Optional notes for the event (e.g., incident description)
  photo_url String? // URL of photo taken during walk (if event_type is 'photo_taken')

  // Relations:
  // [one-to-many] -> bookings (via booking_id) [references]
}

model Reviews {
  id String @id @default(uuid()) // Unique identifier for the review
  booking_id String @unique // Foreign key to the bookings table. Each booking can only have one review in each direction (owner to walker, walker to owner)
  reviewer_user_id String // Foreign key to the users table (who submitted the review)
  reviewee_user_id String // Foreign key to the users table (who received the review)
  rating Int // Star rating (1-5)
  comment String? // Textual review
  created_at DateTime // Timestamp of review creation

  // Relations:
  // [one-to-one] -> bookings (via booking_id) [references]
  // [many-to-one] -> users (via reviewer_user_id) [references]
  // [many-to-one] -> users (via reviewee_user_id) [references]
}

model Transactions {
  id String @id @default(uuid()) // Unique identifier for the transaction
  booking_id String? // Foreign key to the bookings table, if transaction is related to a booking
  payer_user_id String // Foreign key to the users table (who initiated the payment)
  payee_user_id String // Foreign key to the users table (who received the funds)
  amount Float // Total amount of the transaction
  platform_fee Float // Amount retained by the platform
  status String @default("'pending'") // Transaction status: 'pending', 'succeeded', 'failed', 'refunded'
  payment_gateway_id String? // Reference ID from the payment gateway (e.g., Stripe)
  transaction_type String @default("'payment'") // Type of transaction: 'payment', 'payout', 'refund'
  created_at DateTime // Timestamp of transaction creation

  // Relations:
  // [many-to-one] -> bookings (via booking_id) [references]
  // [many-to-one] -> users (via payer_user_id) [references]
  // [many-to-one] -> users (via payee_user_id) [references]
}

model Walker_availabilities {
  id String @id @default(uuid()) // Unique identifier for the availability slot
  walker_profile_id String // Foreign key to the walker_profiles table
  day_of_week Int // Day of the week (0 for Sunday, 1 for Monday, etc.)
  start_time DateTime // Start time of availability slot
  end_time DateTime // End time of availability slot

  // Relations:
  // [many-to-one] -> walker_profiles (via walker_profile_id) [references]
}

